#!/usr/bin/env python3
import json
import sqlite3
import subprocess

import numpy as np
import sqlite_vec
from flask import Flask, jsonify, request

DB_PATH = "/home/user/data/embeddings.db"
ORACLE_PATH = "/app/embed_oracle"
STATS_PATH = "/home/user/stats.json"
EMBEDDING_DIM = 64
EXPECTED_BYTES = EMBEDDING_DIM * 4

app = Flask(__name__)


def get_embedding(text):
    proc = subprocess.run(
        [ORACLE_PATH],
        input=text.encode("utf-8"),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=15,
        check=False,
    )
    if proc.returncode != 0:
        raise RuntimeError(
            f"Oracle failed with exit code {proc.returncode}: "
            f"{proc.stderr.decode('utf-8', 'replace')}"
        )
    raw = proc.stdout
    if len(raw) != EXPECTED_BYTES:
        raise RuntimeError(
            f"Oracle returned {len(raw)} bytes; expected {EXPECTED_BYTES}"
        )
    return np.frombuffer(raw, dtype="<f4").astype(np.float64)


def open_db():
    conn = sqlite3.connect(DB_PATH)
    conn.enable_load_extension(True)
    sqlite_vec.load(conn)
    conn.enable_load_extension(False)
    return conn


@app.get("/stats")
def stats():
    with open(STATS_PATH, "r", encoding="utf-8") as f:
        payload = json.load(f)
    return jsonify(payload)


@app.post("/search")
def search():
    body = request.get_json(silent=False)
    if not isinstance(body, dict):
        return jsonify({"error": "JSON object required"}), 400

    query = body.get("query")
    top_k = body.get("top_k")
    if not isinstance(query, str):
        return jsonify({"error": "query must be a string"}), 400
    if not isinstance(top_k, int) or isinstance(top_k, bool):
        return jsonify({"error": "top_k must be an integer"}), 400
    if top_k <= 0:
        return jsonify([])

    query_vec = get_embedding(query).astype("<f4").tobytes()
    conn = open_db()
    try:
        rows = conn.execute(
            "SELECT d.id, d.text, v.distance FROM docs_vec AS v "
            "JOIN docs AS d ON d.id = v.doc_id "
            "WHERE v.embedding MATCH ? AND k = ? ORDER BY v.distance",
            (query_vec, min(top_k, 50)),
        ).fetchall()
    finally:
        conn.close()
    results = [
        {"id": int(doc_id), "text": text, "score": float(1.0 - distance)}
        for doc_id, text, distance in rows
    ]
    return jsonify(results)


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=8080, debug=False, threaded=True)
